package rentivo_backend.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="payments")
public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="plan_id") private SubscriptionPlan plan; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Column(nullable=false,length=50) private String status="PENDING"; @Column(unique=true) private String providerPaymentId; @Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public User getUser(){return user;} public SubscriptionPlan getPlan(){return plan;} public BigDecimal getAmount(){return amount;} public String getStatus(){return status;} public String getProviderPaymentId(){return providerPaymentId;} public LocalDateTime getCreatedAt(){return createdAt;} public void setId(Long v){id=v;} public void setUser(User v){user=v;} public void setPlan(SubscriptionPlan v){plan=v;} public void setAmount(BigDecimal v){amount=v;} public void setStatus(String v){status=v;} public void setProviderPaymentId(String v){providerPaymentId=v;} }
